/// <summary>
/// InventTransferLine event handlers
/// </summary>
final class NDXInventTransferLine_tbl_EventHandler
{
}

Method.Source:
/// <summary>
/// Post event modified fild
/// </summary>
/// <param name = "_args">argument</param>
[PostHandlerFor(tableStr(InventTransferLine), tableMethodStr(InventTransferLine, modifiedField))]
public static void InventTransferLine_Post_modifiedField(XppPrePostArgs _args)
{
    FieldId fieldId = _args.getArg(identifierStr(_fieldId));
    InventTransferLine inventTransferLine = _args.getThis();
    NDXItemStateTable  itemStateTable;

    switch (fieldId)
    {
        case fieldnum(InventTransferLine, ItemId):

            if(InventTransferTable::find(inventTransferLine.TransferId).KCS_TransferType == KCS_TransferType::Agent)
            {
                itemStateTable = NDXItemStateTable::find(inventTransferLine.ItemId);

                //Info ausgeben
                if(itemStateTable && itemStateTable.ShowInfoItemState && itemStateTable.InfoItemState)
                {
                    info(strFmt(itemStateTable.InfoItemState));
                }
            }

            break;
    }
}
